UPDATE notification_email_deliveries
SET status = 'PENDING', retry_round = retry_round + 1, attempts = 0,
    next_attempt_at = #{now}, claim_token = NULL, lease_until = NULL,
    sent_at = NULL, last_error = NULL, updated_at = #{now}
WHERE id = #{id} AND status = 'FAILED' AND retry_round = #{expectedRound}
